import re

RE = re.compile(r"^(?P<qty>[\d/.]+)\s*(?P<unit>cups?|tbsp|tsp|g|oz)?\s*(?P<name>.+)$")

def to_float(s):
    if '/' in s:
        a, b = s.split('/')
        return int(a) / int(b)
    return float(s)

def parse_ingredient(line):
    m = RE.match(line.strip())
    d = m.groupdict()
    return {"qty": to_float(d["qty"]), "unit": d["unit"].lower(), "name": d["name"]}

